// src/App.js
import { useEffect, useState } from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend
} from "chart.js";

import {
  fetchLoggedUser,
  fetchPRStatus,
  fetchUserRepos
} from "./api/githubApi";

import MonthYearPicker from "./components/MonthYearPicker";

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

function App() {
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");

  const [labels, setLabels] = useState([]);
  const [counts, setCounts] = useState([]);
  const [total, setTotal] = useState(0);
  const [openPRs, setOpenPRs] = useState(0);
  const [closedPRs, setClosedPRs] = useState(0);
  const [mergedPRs, setMergedPRs] = useState(0);

  const [userCreatedAt, setUserCreatedAt] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [commitLabels, setCommitLabels] = useState([]);
  const [commitCounts, setCommitCounts] = useState([]);
  const [totalCommits, setTotalCommits] = useState(0);

  // ✅ Save token from GitHub callback URL
  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    const token = query.get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  // ✅ Load user + repos
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    fetchLoggedUser().then(res => {
      setOwner(res.data.login);          // backend returns full JSON
      setUserCreatedAt(res.data.created_at);
    });

    fetchUserRepos().then(res => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    });
  }, []);

  // 🔹 Helper to call backend
  const callBackend = async (payload) => {
    console.log("Sending payload:", payload);
    const res = await fetchPRStatus(payload);
    console.log("Backend response:", res.data);

    setLabels(res.data.labels || []);
    setCounts(res.data.counts || []);
    setTotal(res.data.total || 0);
    setOpenPRs(res.data.open || 0);
    setClosedPRs(res.data.closed || 0);
    setMergedPRs(res.data.merged || 0);
  };

  // ✅ Today button
  const fetchToday = async () => {
    if (!owner || !selectedRepo) {
      alert("Owner or repository is missing");
      return;
    }

    const today = new Date().toISOString().slice(0, 10);

    const payload = {
      owner,
      repo: selectedRepo,
      startDate: today,
      endDate: today
    };

    try {
      await callBackend(payload);
    } catch (err) {
      console.error(err);
      alert("Error fetching today's PRs");
    }
  };

  // ✅ Analyze button (selected month/year)
  const fetchData = async () => {
    if (!owner || !selectedRepo) {
      alert("Owner or repository is missing");
      return;
    }
    if (!startDate || !endDate) {
      alert("Please select month and year first");
      return;
    }

    const payload = {
      owner,
      repo: selectedRepo,
      startDate,
      endDate
    };

    try {
      await callBackend(payload);
    } catch (err) {
      console.error(err);
      alert("Error fetching PR analytics");
    }
  };

  const data = {
    labels,
    datasets: [
      {
        label: "Pull Requests",
        data: counts,
        backgroundColor: "#4F46E5"
      }
    ]
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>GitHub Analytics Dashboard</h1>

      {!owner && (
        <button
          onClick={() =>
            (window.location.href = "http://localhost:8080/auth/github")
          }
          style={styles.loginBtn}
        >
          Login with GitHub
        </button>
      )}

      {owner && <h3>Logged in as: {owner}</h3>}

      {owner && (
        <>
          <div style={styles.form}>
            {/* Repo dropdown */}
            <select
              value={selectedRepo}
              onChange={e => setSelectedRepo(e.target.value)}
            >
              {repos.map(repo => (
                <option key={repo.id} value={repo.name}>
                  {repo.name}
                </option>
              ))}
            </select>

            {/* Month + Year picker */}
            <MonthYearPicker
              userCreatedAt={userCreatedAt}
              onChange={({ startDate, endDate }) => {
                setStartDate(startDate);
                setEndDate(endDate);
              }}
            />

            <button onClick={fetchData}>Analyze</button>
            <button onClick={fetchToday}>Today</button>
          </div>

          {/* Stats cards */}
          {total > 0 && (
            <div style={styles.cardGrid}>
              <div style={styles.statCard}>Total PRs: {total}</div>
              <div style={{ ...styles.statCard, background: "#DCFCE7" }}>
                Open PRs: {openPRs}
              </div>
              <div style={{ ...styles.statCard, background: "#FEF9C3" }}>
                Closed PRs: {closedPRs}
              </div>
              <div style={{ ...styles.statCard, background: "#DBEAFE" }}>
                Merged PRs: {mergedPRs}
              </div>
            </div>
          )}

          {/* Chart */}
          {labels.length > 0 && (
            <div style={{ width: "90%", maxWidth: 950, marginTop: 30 }}>
              <Bar data={data} />
            </div>
          )}
        </>
      )}
    </div>
  );
}

const styles = {
  container: {
    textAlign: "center",
    padding: 30,
    fontFamily: "Arial",
    background: "#F8FAFC",
    minHeight: "100vh"
  },
  heading: {
    color: "#1E293B"
  },
  form: {
    display: "flex",
    gap: 10,
    justifyContent: "center",
    marginBottom: 30,
    flexWrap: "wrap"
  },
  loginBtn: {
    padding: "10px 20px",
    borderRadius: 6,
    border: "none",
    background: "#111827",
    color: "white",
    fontWeight: "bold",
    cursor: "pointer",
    marginBottom: 20
  },
  cardGrid: {
    display: "flex",
    gap: 12,
    justifyContent: "center",
    marginTop: 20,
    flexWrap: "wrap"
  },
  statCard: {
    padding: "10px 18px",
    borderRadius: 10,
    background: "#E5E7EB",
    fontWeight: 500,
    minWidth: 140
  }
};

export default App;
